// Bridge: el Schedule simula un comando EXTRAER
// para entrar al mismo flujo que Telegram
return [{
  json: {
    message: {
      text: 'EXTRAER',
      chat: { id: 'CONFIGURAR_TU_CHAT_ID' },
      from: { first_name: 'Schedule' }
    },
    _source: 'schedule_trigger'
  }
}];

// Definir las 6 fuentes RSS + datos del chat para pasar adelante
const chatId = $input.first().json.message?.chat?.id || 'CONFIGURAR_TU_CHAT_ID';

const feeds = [
  { url: 'https://news.mit.edu/topic/mitartificial-intelligence2-rss.xml', source: 'MIT News AI' },
  { url: 'https://sloanreview.mit.edu/feed/', source: 'MIT Sloan Review' },
  { url: 'https://www.cio.com/feed/', source: 'CIO.com' },
  { url: 'https://www.wired.com/feed/tag/ai/latest/rss', source: 'Wired AI' },
  { url: 'https://www.wired.com/feed/category/business/latest/rss', source: 'Wired Business' },
  { url: 'https://www.wired.com/feed/category/science/latest/rss', source: 'Wired Science' }
];

return feeds.map(f => ({ json: { ...f, chat_id: chatId } }));

// =============================================
// PARSEAR RSS XML → JSON de articulos
// =============================================
const items = $input.all();
const articles = [];

for (const item of items) {
  const xml = typeof item.json.data === 'string' 
    ? item.json.data 
    : (item.json.body || item.json.response || '');
  const source = item.json.source || 'Unknown';
  const chatId = item.json.chat_id || '';

  if (!xml || typeof xml !== 'string') continue;

  // Parser RSS simple pero robusto
  const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let match;

  while ((match = itemRegex.exec(xml)) !== null) {
    const x = match[1];
    const getTag = (tag) => {
      const m = x.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)</' + tag + '>', 'i'));
      if (!m) return '';
      return m[1]
        .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
        .replace(/<[^>]+>/g, '')
        .trim();
    };

    const title = getTag('title');
    const link = getTag('link') || getTag('guid');
    const description = getTag('description').substring(0, 800);
    const pubDate = getTag('pubDate');

    if (title && link) {
      articles.push({
        title,
        link,
        description,
        pubDate,
        source,
        chat_id: chatId
      });
    }
  }
}

if (articles.length === 0) {
  return [{ json: { _no_articles: true, chat_id: items[0]?.json?.chat_id || '' } }];
}

// Deduplicar por link
const seen = new Set();
const unique = articles.filter(a => {
  if (seen.has(a.link)) return false;
  seen.add(a.link);
  return true;
});

// Retornar como un solo item con array (para facilitar merge posterior)
return [{ json: { articles: unique, total: unique.length, chat_id: unique[0]?.chat_id || '' } }];

// =============================================
// FILTRAR DUPLICADOS + CARGAR CONTEXT GRAPH + RAG
// =============================================
// ORDEN CRITICO: Context Graph PRIMERO, RAG DESPUES
// Esto le da al AI la "memoria institucional" antes
// de consultar el conocimiento de marca.
// =============================================

const items = $input.all();

// Separar datos RSS de datos existentes en sheets
let newArticles = [];
let existingLinks = new Set();
let chatId = '';

for (const item of items) {
  if (item.json.articles) {
    // Viene del parser RSS
    newArticles = item.json.articles;
    chatId = item.json.chat_id || chatId;
  } else if (item.json.link) {
    // Viene de Google Sheets (articulos existentes)
    existingLinks.add(item.json.link);
  }
}

// Filtrar los que ya existen
const freshArticles = newArticles.filter(a => !existingLinks.has(a.link));

if (freshArticles.length === 0) {
  return [{ json: { _no_new_articles: true, chat_id: chatId } }];
}

// =============================================
// CONTEXT GRAPH - Memoria Institucional Aura Studio
// =============================================
// En produccion: leer desde Google Sheets/Supabase
// Por ahora, estructura base que se va llenando
const contextGraph = {
  brand: 'Aura Studio',
  philosophy: 'Work fast, live slow',
  historial_publicaciones: [],
  temas_recientes: [],
  restricciones: [
    'No repetir temas de las ultimas 2 semanas',
    'Alternar educativo y tendencias',
    'Maximo 2 posts promocionales por semana',
    'NUNCA usar estetica tech fria, robots, circuitos',
    'SIEMPRE mantener tono reflexivo, sofisticado, humano',
    'NO tech bros, NO vendedores agresivos, NO corporativo frio'
  ],
  calendario_editorial: {
    lunes: 'educativo_tip',
    martes: 'tendencia_industria',
    miercoles: 'caso_exito',
    jueves: 'detras_de_camaras',
    viernes: 'recurso_herramienta',
    sabado: 'reflexion_lifestyle',
    domingo: 'inspiracion'
  },
  decisiones_previas: [],
  metricas_engagement: {}
};

// =============================================
// RAG - Identidad de Marca Aura Studio
// =============================================
const ragBrand = {
  identidad: {
    nombre: 'Aura Studio',
    tagline: 'Work fast, live slow',
    enfoque: 'Studio de pensamiento estrategico en automatizacion con IA',
    tono: 'Reflexivo, sofisticado, humano, calido',
    no_somos: 'Tech bros, vendedores agresivos, corporativos frios'
  },
  estetica_visual: {
    estilo: 'Fotografia cinematografica editorial',
    naturaleza: 'Latinoamericana/tropical: frailejones de paramo colombiano, hojas de monstera, frutas tropicales (uchuvas, maracuya, mangos)',
    iluminacion: 'Luz natural: golden hour, neblina de montana',
    paleta: 'Verdes profundos, crema, beige, dorados sutiles',
    personas: 'Reales, diversas, en conexion con naturaleza',
    evitar: 'Estetica tech fria, robots, circuitos, oficinas genericas'
  },
  tipografia: {
    titulos: 'Kaneda Gothic Medium/Bold',
    nota: 'El logo se agrega como overlay al final'
  },
  cta_permitidos: ['comenta', 'guarda', 'comparte'],
  pilares_contenido: [
    { pilar: 'IA y Automatizacion', porcentaje: 35 },
    { pilar: 'Liderazgo y Negocios', porcentaje: 25 },
    { pilar: 'Reflexion y Lifestyle', porcentaje: 20 },
    { pilar: 'Tendencias Tech', porcentaje: 20 }
  ]
};

// Preparar batch para scoring AI
const articleBatch = freshArticles.slice(0, 15).map((a, i) => ({
  index: i,
  title: a.title,
  description: a.description.substring(0, 400),
  source: a.source,
  link: a.link,
  pubDate: a.pubDate
}));

return [{
  json: {
    chat_id: chatId,
    context_graph: contextGraph,
    rag_brand: ragBrand,
    articles_to_score: articleBatch,
    articles_full: freshArticles.slice(0, 15),
    total_new: freshArticles.length
  }
}];

