// =============================================
// GUARDRAILS: Validar scoring del AI
// =============================================
const aiResponse = $input.first().json;
const prevData = $('Filter + Context Graph + RAG').first().json;

let scored;
try {
  const content = aiResponse.choices?.[0]?.message?.content
    || aiResponse.message?.content
    || aiResponse.text
    || JSON.stringify(aiResponse);

  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON found');
  scored = JSON.parse(jsonMatch[0]);
} catch (e) {
  // GUARDRAIL: Si no se puede parsear, asignar scores basicos
  scored = {
    scored_articles: prevData.articles_to_score.map((a, i) => ({
      index: i,
      score: 50,
      categoria: 'IA',
      resumen: a.description?.substring(0, 100) || a.title,
      datos_clave: [],
      tipo_sugerido: 'resumen',
      aura_fit: 'medio',
      razon_score: 'Score por defecto - AI no retorno JSON valido'
    }))
  };
}

const articles = scored.scored_articles || [];
const fullArticles = prevData.articles_full || [];

// GUARDRAILS de validacion
const validated = articles.map(a => {
  const issues = [];

  // Score debe estar entre 1-100
  if (!a.score || a.score < 1 || a.score > 100) {
    a.score = Math.min(100, Math.max(1, a.score || 50));
    issues.push('Score ajustado a rango valido');
  }

  // Debe tener categoria
  const validCats = ['IA', 'Liderazgo', 'Negocios', 'Ciencia', 'Startups', 'Cultura'];
  if (!validCats.includes(a.categoria)) {
    a.categoria = 'IA';
    issues.push('Categoria ajustada a default');
  }

  // Debe tener resumen
  if (!a.resumen || a.resumen.length < 10) {
    issues.push('Resumen demasiado corto o ausente');
  }

  a.guardrail_issues = issues;
  return a;
});

// Combinar con datos completos de articulos
const enriched = validated.map(a => {
  const full = fullArticles[a.index] || {};
  return {
    ...full,
    score: a.score,
    categoria: a.categoria,
    resumen: a.resumen || full.description?.substring(0, 200),
    datos_clave: (a.datos_clave || []).join(' | '),
    tipo_sugerido: a.tipo_sugerido || 'resumen',
    aura_fit: a.aura_fit || 'medio',
    estado: 'nuevo',
    extractedAt: new Date().toISOString(),
    guardrail_issues: a.guardrail_issues?.join('; ') || ''
  };
});

// Ordenar por score descendente
enriched.sort((a, b) => b.score - a.score);

return [{
  json: {
    chat_id: prevData.chat_id,
    articles_scored: enriched,
    best_article: enriched[0] || null,
    total_scored: enriched.length
  }
}];

// Preparar datos para guardar estado y mensaje de Telegram
const data = $('Guardrails Scoring').first().json;
const best = data.best_article;

if (!best) {
  return [{ json: { chat_id: data.chat_id, _no_articles: true } }];
}

// Datos para actualizar sheet estado
const estado = {
  chat_id: data.chat_id,
  articulo_actual_link: best.link,
  articulo_actual_title: best.title,
  carrusel_actual: '',
  fase: 'esperando_aprobacion',
  updated_at: new Date().toISOString()
};

// Mensaje formateado para Telegram
const datosClaveText = best.datos_clave
  ? best.datos_clave.split(' | ').map(d => '  • ' + d).join('\n')
  : '  (sin datos clave)';

const message = `🔔 *ARTICULO PARA CARRUSEL*\n\n` +
  `📰 *${best.title}*\n\n` +
  `⭐ Score: ${best.score}/100\n` +
  `📂 Categoria: ${best.categoria}\n` +
  `🔗 Fuente: ${best.source}\n` +
  `🌿 Aura Fit: ${best.aura_fit || 'medio'}\n\n` +
  `📝 *Resumen:*\n${best.resumen}\n\n` +
  `📊 *Datos clave:*\n${datosClaveText}\n\n` +
  `---\n` +
  `✅ Escribe *SI* para generar carrusel\n` +
  `❌ Escribe *NO* para descartar\n` +
  `⏭️ Escribe *SKIP* para ver siguiente`;

return [{ json: { ...estado, telegram_message: message, total_available: data.total_scored } }];

// Leer estado y preparar para generacion de carrusel
const estado = $input.first().json;
const chatId = $('Router Comandos').first().json.message?.chat?.id || estado.chat_id;

if (!estado.articulo_actual_link || estado.fase !== 'esperando_aprobacion') {
  return [{
    json: {
      _error: true,
      chat_id: chatId,
      message: '⚠️ No hay articulo pendiente de aprobacion. Usa EXTRAER primero.'
    }
  }];
}

return [{
  json: {
    chat_id: chatId,
    articulo_link: estado.articulo_actual_link,
    articulo_title: estado.articulo_actual_title,
    fase: estado.fase
  }
}];

// Encontrar el articulo aprobado y preparar prompt de carrusel
const prevData = $('Validar Estado SI').first().json;
const allArticles = $input.all().map(i => i.json);
const article = allArticles.find(a => a.link === prevData.articulo_link);

if (!article) {
  return [{ json: { _error: true, chat_id: prevData.chat_id, message: '⚠️ Articulo no encontrado en la base de datos.' } }];
}

// =============================================
// CONTEXT GRAPH + RAG para generacion de carrusel
// ORDEN: Context Graph PRIMERO, RAG DESPUES
// =============================================
const contextGraph = {
  restricciones: [
    'No repetir temas de las ultimas 2 semanas',
    'Mantener tono reflexivo, sofisticado, humano, calido',
    'NUNCA usar estetica tech fria',
    'Equilibrar contenido educativo con tendencias'
  ],
  publicaciones_recientes: [],
  filosofia: 'Work fast, live slow'
};

const ragBrand = {
  nombre: 'Aura Studio',
  tono: 'Reflexivo, sofisticado, humano, calido',
  no_somos: 'Tech bros, vendedores agresivos, corporativos frios',
  estetica: {
    estilo: 'Fotografia cinematografica editorial',
    naturaleza: 'Latinoamericana/tropical: frailejones de paramo colombiano, hojas de monstera, frutas tropicales',
    luz: 'Natural: golden hour, neblina de montana',
    paleta: 'Verdes profundos, crema, beige, dorados sutiles',
    personas: 'Reales, diversas, en conexion con naturaleza',
    evitar: 'Estetica tech fria, robots, circuitos, oficinas genericas'
  },
  tipografia: 'Kaneda Gothic Medium/Bold para titulos',
  cta_permitidos: ['comenta', 'guarda', 'comparte']
};

return [{
  json: {
    chat_id: prevData.chat_id,
    article,
    context_graph: contextGraph,
    rag_brand: ragBrand
  }
}];

