// =============================================
// GUARDRAILS: Validar carrusel generado
// =============================================
const aiResponse = $input.first().json;
const prevData = $('Preparar Prompt Carrusel').first().json;

let carousel;
try {
  const content = aiResponse.choices?.[0]?.message?.content
    || aiResponse.message?.content
    || aiResponse.text
    || JSON.stringify(aiResponse);

  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON found in AI response');
  carousel = JSON.parse(jsonMatch[0]);
} catch (e) {
  return [{
    json: {
      _error: true,
      chat_id: prevData.chat_id,
      message: '⚠️ Error al parsear carrusel del AI. Intenta REGENERAR.\n\nError: ' + e.message
    }
  }];
}

// =============================================
// VALIDACIONES DE GUARDRAILS
// =============================================
const issues = [];
const slides = carousel.slides || [];

// G1: Debe tener entre 5-7 slides
if (slides.length < 4) issues.push('Menos de 4 slides');
if (slides.length > 10) issues.push('Mas de 10 slides');

// G2: Slide 1 debe ser portada con hook corto
if (slides[0]) {
  if (slides[0].titulo && slides[0].titulo.split(' ').length > 12) {
    issues.push('Hook de portada muy largo (max 8-10 palabras)');
  }
}

// G3: Cada slide debe tener prompt_imagen
for (const s of slides) {
  if (!s.prompt_imagen || s.prompt_imagen.length < 20) {
    issues.push(`Slide ${s.numero}: prompt de imagen ausente o muy corto`);
  }
}

// G4: Prompts NO deben contener estetica tech
const forbiddenInPrompts = ['robot', 'circuit', 'neon', 'cyberpunk', 'matrix', 'binary code', 'motherboard', 'generic office'];
for (const s of slides) {
  if (s.prompt_imagen) {
    const promptLower = s.prompt_imagen.toLowerCase();
    for (const word of forbiddenInPrompts) {
      if (promptLower.includes(word)) {
        issues.push(`Slide ${s.numero}: prompt contiene "${word}" (PROHIBIDO en Aura Studio)`);
        // Auto-fix: remover la palabra
        s.prompt_imagen = s.prompt_imagen.replace(new RegExp(word, 'gi'), 'natural elements');
      }
    }
  }
}

// G5: Debe tener caption
if (!carousel.caption || carousel.caption.length < 10) {
  issues.push('Caption ausente o muy corto');
}

// G6: CTA debe ser uno de los permitidos
const allowedCTAs = ['comenta', 'guarda', 'comparte'];
if (carousel.cta && !allowedCTAs.includes(carousel.cta.toLowerCase())) {
  carousel.cta = 'comenta'; // Auto-fix
  issues.push('CTA ajustado a "comenta" (no era uno de los permitidos)');
}

// G7: Hashtags deben incluir #AuraStudio y #WorkFastLiveSlow
if (carousel.hashtags && Array.isArray(carousel.hashtags)) {
  if (!carousel.hashtags.some(h => h.toLowerCase().includes('aurastudio'))) {
    carousel.hashtags.unshift('#AuraStudio');
  }
  if (!carousel.hashtags.some(h => h.toLowerCase().includes('workfastliveslow'))) {
    carousel.hashtags.splice(1, 0, '#WorkFastLiveSlow');
  }
}

carousel.guardrail_status = issues.length === 0 ? 'APROBADO' : 'CON_OBSERVACIONES';
carousel.guardrail_issues = issues;

// Formatear mensaje de Telegram
let tgMessage = '🎨 *CARRUSEL GENERADO*\n\n';
tgMessage += '📑 *Slides:*\n';
for (const s of slides) {
  tgMessage += `${s.numero}. [${s.tipo}] ${s.titulo}\n`;
  if (s.texto) tgMessage += `   ${s.texto.substring(0, 80)}...\n`;
}
tgMessage += `\n✍️ *Caption:*\n${carousel.caption}\n`;
tgMessage += `\n#️⃣ *Hashtags:* ${(carousel.hashtags || []).join(' ')}\n`;
tgMessage += `\n🎵 *Musica:* ${carousel.musica_sugerida || 'No sugerida'}\n`;
tgMessage += `🎯 *CTA:* ${carousel.cta}\n`;
tgMessage += `📱 *Plataforma:* ${carousel.plataforma_ideal || 'ambas'}\n`;

if (issues.length > 0) {
  tgMessage += `\n⚠️ *Observaciones Guardrails:*\n`;
  issues.forEach(i => { tgMessage += `  • ${i}\n`; });
}

tgMessage += `\n---\n`;
tgMessage += `✅ Escribe *LISTO* para guardar\n`;
tgMessage += `🔄 Escribe *REGENERAR* para nuevo intento`;

return [{
  json: {
    chat_id: prevData.chat_id,
    carousel: carousel,
    carousel_json: JSON.stringify(carousel),
    telegram_message: tgMessage,
    article: prevData.article
  }
}];

// =============================================
// DESCARTAR articulo actual + buscar siguiente
// =============================================
const items = $input.all();
const chatId = $('Router Comandos').first().json.message?.chat?.id || '';

let estado = null;
const articulos = [];

for (const item of items) {
  if (item.json.fase) {
    estado = item.json;
  } else if (item.json.link) {
    articulos.push(item.json);
  }
}

if (!estado || !estado.articulo_actual_link) {
  return [{ json: { _error: true, chat_id: chatId, message: '⚠️ No hay articulo actual. Usa EXTRAER.' } }];
}

// Encontrar siguiente mejor articulo con estado='nuevo'
const available = articulos
  .filter(a => a.estado === 'nuevo' && a.link !== estado.articulo_actual_link)
  .sort((a, b) => (parseInt(b.score) || 0) - (parseInt(a.score) || 0));

const next = available[0] || null;

const updates = {
  discard_link: estado.articulo_actual_link,
  chat_id: chatId
};

if (next) {
  const datosClaveText = next.datos_clave
    ? next.datos_clave.split(' | ').map(d => '  • ' + d).join('\n')
    : '  (sin datos clave)';

  updates.next_article = next;
  updates.new_estado = {
    chat_id: chatId,
    articulo_actual_link: next.link,
    articulo_actual_title: next.title,
    carrusel_actual: '',
    fase: 'esperando_aprobacion',
    updated_at: new Date().toISOString()
  };
  updates.telegram_message = `❌ Articulo descartado.\n\n` +
    `🔔 *SIGUIENTE ARTICULO*\n\n` +
    `📰 *${next.title}*\n\n` +
    `⭐ Score: ${next.score}/100\n` +
    `📂 Categoria: ${next.categoria}\n` +
    `🔗 Fuente: ${next.source}\n\n` +
    `📝 *Resumen:*\n${next.resumen}\n\n` +
    `📊 *Datos clave:*\n${datosClaveText}\n\n` +
    `---\n` +
    `✅ *SI* | ❌ *NO* | ⏭️ *SKIP*`;
} else {
  updates.telegram_message = '📭 No hay mas articulos disponibles. Usa EXTRAER para buscar nuevos.';
  updates.new_estado = {
    chat_id: chatId,
    articulo_actual_link: '',
    articulo_actual_title: '',
    carrusel_actual: '',
    fase: 'idle',
    updated_at: new Date().toISOString()
  };
}

return [{ json: updates }];

// =============================================
// SKIP: Buscar siguiente SIN descartar el actual
// =============================================
const items = $input.all();
const chatId = $('Router Comandos').first().json.message?.chat?.id || '';

let estado = null;
const articulos = [];

for (const item of items) {
  if (item.json.fase) {
    estado = item.json;
  } else if (item.json.link) {
    articulos.push(item.json);
  }
}

if (!estado) {
  return [{ json: { chat_id: chatId, telegram_message: '⚠️ No hay estado activo. Usa EXTRAER.', new_estado: { chat_id: chatId, fase: 'idle', updated_at: new Date().toISOString(), articulo_actual_link: '', articulo_actual_title: '', carrusel_actual: '' } } }];
}

const available = articulos
  .filter(a => a.estado === 'nuevo' && a.link !== estado.articulo_actual_link)
  .sort((a, b) => (parseInt(b.score) || 0) - (parseInt(a.score) || 0));

const next = available[0] || null;

if (next) {
  const datosClaveText = next.datos_clave
    ? next.datos_clave.split(' | ').map(d => '  • ' + d).join('\n')
    : '';

  return [{
    json: {
      chat_id: chatId,
      new_estado: {
        chat_id: chatId,
        articulo_actual_link: next.link,
        articulo_actual_title: next.title,
        carrusel_actual: '',
        fase: 'esperando_aprobacion',
        updated_at: new Date().toISOString()
      },
