// Guardrails para carrusel regenerado (misma logica)
const aiResponse = $input.first().json;
const prevData = $('Preparar Regeneracion').first().json;

let carousel;
try {
  const content = aiResponse.choices?.[0]?.message?.content || aiResponse.message?.content || aiResponse.text || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON');
  carousel = JSON.parse(jsonMatch[0]);
} catch (e) {
  return [{ json: { _error: true, chat_id: prevData.chat_id, message: '⚠️ Error regenerando. Intenta de nuevo.' } }];
}

// Guardrails basicos
const forbidden = ['robot', 'circuit', 'neon', 'cyberpunk', 'generic office'];
for (const s of (carousel.slides || [])) {
  if (s.prompt_imagen) {
    for (const w of forbidden) {
      s.prompt_imagen = s.prompt_imagen.replace(new RegExp(w, 'gi'), 'tropical nature');
    }
  }
}

if (carousel.hashtags && !carousel.hashtags.some(h => h.includes('AuraStudio'))) {
  carousel.hashtags.unshift('#AuraStudio');
}

let msg = '🔄 *CARRUSEL REGENERADO*\n\n📑 *Slides:*\n';
for (const s of (carousel.slides || [])) {
  msg += `${s.numero}. [${s.tipo}] ${s.titulo}\n`;
}
msg += `\n✍️ *Caption:* ${carousel.caption}\n`;
msg += `#️⃣ ${(carousel.hashtags || []).join(' ')}\n`;
msg += `🎵 ${carousel.musica_sugerida || '-'}\n🎯 ${carousel.cta}\n`;
msg += `\n---\n✅ *LISTO* para guardar | 🔄 *REGENERAR* de nuevo`;

return [{ json: { chat_id: prevData.chat_id, carousel_json: JSON.stringify(carousel), telegram_message: msg, article: prevData.article } }];
